<script lang="ts">import {getContext} from 'svelte';import type {I18nState} from '../../../../../lib/i18n/i18n.svelte';import {createFraudReviewState} from '../state/fraudReviewState.svelte';const i18n=getContext<I18nState>('i18n');const selection=getContext<{warehouseId:number|null}>('warehouseSelection');const vm=createFraudReviewState();let drafts=$state<Record<number,string>>({});$effect(()=>{const w=selection?.warehouseId;void vm.load(w??null);});async function save(id:number){await vm.updateMemo(id,drafts[id]??'');}async function push(id:number){if(confirm('¿Liberar este pedido para que vuelva a la cola de preparación?'))await vm.push(id,selection?.warehouseId??null);}</script>
<section class="page"><header><div><p class="eyebrow">ABELLIS · SMART WMS</p><h1>{i18n.t('Revisión de pedidos')}</h1><p>{i18n.t('Revisa los pedidos retenidos, guarda observaciones y autoriza su retorno a preparación.')}</p></div><button onclick={()=>void vm.load(selection?.warehouseId??null)}>{i18n.t('Actualizar')}</button></header>{#if vm.error}<p class="error" role="alert">{vm.error}</p>{/if}
{#if vm.loading}<p>{i18n.t('Cargando…')}</p>{:else if vm.rows.length===0}<p class="empty">{i18n.t('No hay pedidos retenidos para revisión.')}</p>{:else}<div class="table-wrap"><table><thead><tr><th>{i18n.t('Pedido')}</th><th>{i18n.t('Cliente')}</th><th>{i18n.t('Teléfono')}</th><th>{i18n.t('Origen')}</th><th>{i18n.t('Fecha')}</th><th>{i18n.t('Observaciones')}</th><th>{i18n.t('Acciones')}</th></tr></thead><tbody>{#each vm.rows as r (r.salesOrderId)}<tr><td>{r.salesOrderNumber}</td><td>{r.customerName??'—'}</td><td>{r.customerPhone??'—'}</td><td>{r.orderOrigin??r.orderSource??'—'}</td><td>{r.createdAt??'—'}</td><td><textarea rows="2" value={drafts[r.salesOrderId]??r.memo??''} oninput={e=>drafts[r.salesOrderId]=e.currentTarget.value}></textarea><button onclick={()=>void save(r.salesOrderId)} disabled={vm.saving}>{i18n.t('Guardar nota')}</button></td><td><button class="primary" onclick={()=>void push(r.salesOrderId)} disabled={vm.saving}>{i18n.t('Enviar a preparación')}</button></td></tr>{/each}</tbody></table></div>{/if}</section>
<style>.page{max-width:78rem;margin:1.4rem auto;padding:0 1.1rem;color:var(--ink)}header{display:flex;justify-content:space-between;align-items:center;gap:1rem;margin-bottom:1rem}h1{margin:0;font:700 1.6rem var(--disp)}header p{color:var(--slate);font-size:.9rem}.eyebrow{font:600 .65rem var(--disp);letter-spacing:.14em}button{border:1px solid var(--line);border-radius:8px;padding:.5rem .7rem;background:var(--card);color:var(--ink);cursor:pointer}.primary{background:var(--navy);color:white;border-color:var(--navy)}.error{color:var(--danger)}.empty{color:var(--slate);padding:2rem 0}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:12px;background:var(--card)}table{width:100%;border-collapse:collapse;min-width:900px;font-size:.82rem}th,td{text-align:left;padding:.65rem;border-bottom:1px solid var(--line);vertical-align:top}th{color:var(--slate);font-size:.7rem;text-transform:uppercase}textarea{width:220px;min-height:54px;border:1px solid var(--line);border-radius:8px;padding:.5rem;background:var(--card);color:var(--ink);font:inherit;display:block;margin-bottom:.35rem}</style>